// Writes src/country-names.generated.ts with the names of the supported
// countries in every app language, taken from the CLDR data in Node.js.
// Hermes (the app's JavaScript engine) has no Intl.DisplayNames, so the names
// ship as data. Run after changing supportedCountries:
//   pnpm --filter @shareride/i18n generate:countries
import { writeFileSync } from "node:fs";
import { supportedCountries } from "@shareride/domain";
import { locales } from "../src/locales.ts";

const lines = [
  "// Generated by scripts/generate-country-names.ts from CLDR data. Do not edit.",
  'import type { SupportedCountry } from "@shareride/domain";',
  'import type { Locale } from "./locales.ts";',
  "",
  "export const countryNames: Readonly<Record<Locale, Readonly<Record<SupportedCountry, string>>>> = {",
];
for (const locale of locales) {
  const names = new Intl.DisplayNames([locale], { type: "region" });
  lines.push(`  ${locale}: {`);
  for (const country of supportedCountries) {
    lines.push(`    ${country}: ${JSON.stringify(names.of(country))},`);
  }
  lines.push("  },");
}
lines.push("};", "");

writeFileSync(new URL("../src/country-names.generated.ts", import.meta.url), lines.join("\n"));
